let LANG=D.settings.lang==='ar'?'ar':'en';const orig=new WeakMap();
function walk(n){const w=document.createTreeWalker(n,NodeFilter.SHOW_TEXT);let t;while(t=w.nextNode()){const pn=t.parentNode&&t.parentNode.nodeName;if(pn==='SCRIPT'||pn==='STYLE')continue;const o=orig.has(t)?orig.get(t):t.nodeValue,k=o.trim();if(LANG==='ar'&&AR[k]){if(!orig.has(t))orig.set(t,o);t.nodeValue=o.replace(k,AR[k])}else if(LANG==='en'&&orig.has(t))t.nodeValue=orig.get(t)}}
function applyLang(){document.documentElement.dir=LANG==='ar'?'rtl':'ltr';document.documentElement.lang=LANG;$('#lang').textContent=LANG==='ar'?'English':'عربي';render();walk(document.body)}
new MutationObserver(ms=>{if(LANG!=='ar')return;ms.forEach(m=>m.addedNodes.forEach(n=>walk(n.nodeType===3?n.parentNode:n)))}).observe(document.body,{childList:true,subtree:true});
$('#lang').onclick=()=>{LANG=LANG==='ar'?'en':'ar';D.settings.lang=LANG;Api.save(D);applyLang()};
if(LANG==='ar')applyLang();
